  const metaView=detailSection==="clusters"?<ComponentClusterList title="Meta 集群列表" description="选择集群进入 Meta 控制面板" types={["meta"]} relations={relations} currentClusterId={cluster.id} onOpenRelations={()=>navigate(`/clusters/${cluster.id}/meta?section=relations`)} onOpenTopology={openTopology} onOpenCluster={openComponentConsole}/>:detailSection==="relations"?<RelationManager title="Meta 关联列表" description="查看主动关联当前或其他 EventMesh 的 Meta 集群" types={["meta"]} relations={relations} currentClusterId={cluster.id} eventMeshClusters={clusters} onAdd={(ids)=>addRelations(cluster.id,ids)} onRemove={removeRelation} onOpenTopology={openTopology} metaInitiated/>:<ComponentOverview title="Meta 集群概要" description="汇总主动关联当前 EventMesh 的 Meta 集群与仲裁节点" types={["meta"]} relations={relations} currentClusterId={cluster.id} onOpenList={()=>navigate(`/clusters/${cluster.id}/meta?section=clusters`)} onOpenRelations={()=>navigate(`/clusters/${cluster.id}/meta?section=relations`)}/>;
  const openStorageConsole=(item)=>navigate(storageClusterConsolePath(cluster.id,item.type,item.id));
