  const topicAction=<Button type="primary" icon={<PlusOutlined/>} onClick={()=>setTopicOpen(true)}>添加 Topic</Button>;
  const topicRows=topicRecords.map((item,index)=>{const storage=storageClusters.find((candidate)=>candidate.id===item.storageClusterId);return [<strong>{item.name}</strong>,storage?`${storage.type==="kafka"?"Kafka":"RocketMQ"} · ${storage.name}`:"未指定",item.partitions,item.replicas,index<cluster.topics.length?`${(12.8-index*1.4).toFixed(1)}K/s`:"0/s",<span className="mock-status healthy"><CheckCircleOutlined/>正常</span>];});
  const topicView=detailSection==="list"?<ModuleTable title="Topic 列表" description="当前集群的业务 Topic 与物理存储位置" columns={["Topic 名称","存储集群","分区 / 队列","副本","流入速率","状态"]} rows={topicRows} action={topicAction}/>:<div className="mock-stacked-modules"><div className="panel mock-module-actionbar"><div><strong>Topic 管理</strong><span>创建业务 Topic，并同步写入所选 Kafka 或 RocketMQ 集群</span></div>{topicAction}</div><ModuleMonitoringOverview title="Topic 监控概览" description="主题可用性、分区负载与消息吞吐" kpis={[{label:"Topic 总数",value:topicRecords.length,note:"全部可用"},{label:"分区总数",value:topicRecords.reduce((sum,item)=>sum+Number(item.partitions||0),0),note:"无离线分区"},{label:"流入速率",value:formatRate(cluster.inRate),note:"较前一小时 +4.8%"},{label:"流出速率",value:formatRate(cluster.outRate),note:"消费保持稳定"},{label:"消息存储",value:"1.84 TB",note:"使用率 38%"}]} charts={[{title:"Topic 吞吐趋势",description:"全部 Topic 流入与流出速率",unit:"K 条/s",series:[{name:"流入",data:mockMessageSeries.inbound},{name:"流出",data:mockMessageSeries.outbound}]},{title:"分区负载趋势",description:"分区写入与读取负载",unit:"%",series:[{name:"写入负载",data:[38,42,45,43,48,51,49,54,52,57,55,58]},{name:"读取负载",data:[31,34,36,38,40,39,43,45,44,48,47,49]}]}]} health={[{label:"可用 Topic",value:`${topicRecords.length} / ${topicRecords.length}`,note:"全部正常"},{label:"离线分区",value:"0",note:"无异常"},{label:"副本不足",value:"0",note:"副本同步正常"},{label:"热点 Topic",value:"1",note:"order-created 接近阈值",warning:true}]}/></div>;
